/**
 * Stamps a fresh version into the service worker before every build.
 *
 * The service worker's `activate` handler deletes caches that do not match its
 * VERSION. With VERSION hardcoded that deleted nothing, so the previous build's
 * cached app-shell HTML survived every deploy — and because navigations are
 * network-first with a 3s timeout, a shop on a slow connection would be served
 * that stale HTML, which points at chunks the server no longer has. The app
 * breaks and reloading serves the same stale page again.
 *
 * Runs BEFORE `next build`, not after, so the generated file is in `public/`
 * when Next packages it — a postbuild step would be missed by Vercel.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const template = readFileSync(join(root, "src", "sw.template.js"), "utf8");

// Any value that changes per build works. A timestamp is enough and needs no
// coordination with Next's BUILD_ID, which does not exist until after build.
const version = `duka-${new Date().toISOString().replace(/[-:.TZ]/g, "").slice(0, 14)}`;

if (!template.includes("__SW_VERSION__")) {
  console.error("build-sw: template is missing the __SW_VERSION__ placeholder");
  process.exit(1);
}

writeFileSync(
  join(root, "public", "sw.js"),
  `// GENERATED by scripts/build-sw.mjs — edit src/sw.template.js instead.\n` +
    template.replace("__SW_VERSION__", version),
  "utf8",
);

console.log(`build-sw: wrote public/sw.js at version ${version}`);
